def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="dq",
        description="Data quality rule validation and lineage tracing.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    validate_parser = subparsers.add_parser(
        "validate",
        help="validate records from a UTF-8 JSON object on standard input",
    )
    validate_parser.set_defaults(handler=_run_validate)

    batch_validate_parser = subparsers.add_parser(
        "batch-validate",
        help="validate batch-level cross-record rules from a UTF-8 JSON "
        "object on standard input",
    )
    batch_validate_parser.set_defaults(handler=_run_batch_validate)

    profile_parser = subparsers.add_parser(
        "profile",
        help="profile records and generate validate rule candidates from "
        "a UTF-8 JSON object on standard input",
    )
    profile_parser.set_defaults(handler=_run_profile)

    exemptions_parser = subparsers.add_parser(
        "exemptions",
        help="apply manual exemptions to a dq validate result from a "
        "UTF-8 JSON object on standard input",
    )
    exemptions_parser.set_defaults(handler=_run_exemptions)

    lineage_parser = subparsers.add_parser(
        "lineage",
        help="trace upstream/downstream lineage from a UTF-8 JSON object "
        "on standard input",
    )
    lineage_parser.set_defaults(handler=_run_lineage)

    field_lineage_parser = subparsers.add_parser(
        "field-lineage",
        help="trace upstream/downstream field-level lineage from a UTF-8 "
        "JSON object on standard input",
    )
    field_lineage_parser.set_defaults(handler=_run_field_lineage)

    lineage_paths_parser = subparsers.add_parser(
        "lineage-paths",
        help="explain ordered upstream/downstream lineage paths from a "
        "UTF-8 JSON object on standard input",
    )
    lineage_paths_parser.set_defaults(handler=_run_lineage_paths)

    field_lineage_paths_parser = subparsers.add_parser(
        "field-lineage-paths",
        help="explain ordered upstream/downstream field-level lineage paths "
        "from a UTF-8 JSON object on standard input",
    )
    field_lineage_paths_parser.set_defaults(handler=_run_field_lineage_paths)

    sample_lineage_parser = subparsers.add_parser(
        "sample-lineage",
        help="trace upstream/downstream sample-level lineage from a UTF-8 "
        "JSON object on standard input",
    )
    sample_lineage_parser.set_defaults(handler=_run_sample_lineage)

    correlate_parser = subparsers.add_parser(
        "correlate",
        help="group violation results into cross-rule correlation events "
        "from a UTF-8 JSON object on standard input",
    )
    correlate_parser.set_defaults(handler=_run_correlate)

    correlate_links_parser = subparsers.add_parser(
        "correlate-links",
        help="group violation results across linked samples into "
        "cross-dataset correlation events from a UTF-8 JSON object on "
        "standard input",
    )
    correlate_links_parser.set_defaults(handler=_run_correlate_links)

    violation_origins_parser = subparsers.add_parser(
        "violation-origins",
        help="analyze upstream/self origin and downstream impact evidence "
        "of violated targets from a UTF-8 JSON object on standard input",
    )
    violation_origins_parser.set_defaults(handler=_run_violation_origins)

    field_impact_parser = subparsers.add_parser(
        "field-impact",
        help="analyze downstream field-level quality impact from a UTF-8 "
        "JSON object on standard input",
    )
    field_impact_parser.set_defaults(handler=_run_field_impact)

    query_results_parser = subparsers.add_parser(
        "query-results",
        help="filter complete composite rule results by rule id, severity "
        "or record locator from a UTF-8 JSON object on standard input",
    )
    query_results_parser.set_defaults(handler=_run_query_results)

    snapshot_diff_parser = subparsers.add_parser(
        "snapshot-diff",
        help="compare violated results of two quality check snapshots over "
        "the shared lineage graph from a UTF-8 JSON object on standard "
        "input",
    )
    snapshot_diff_parser.set_defaults(handler=_run_snapshot_diff)

    reference_integrity_parser = subparsers.add_parser(
        "reference-integrity",
        help="validate cross-dataset reference integrity rules from a "
        "UTF-8 JSON object on standard input",
    )
    reference_integrity_parser.set_defaults(handler=_run_reference_integrity)

    quality_gates_parser = subparsers.add_parser(
        "quality-gates",
        help="aggregate single-field rule failure ratios into dataset-level "
        "quality gates from a UTF-8 JSON object on standard input",
    )
    quality_gates_parser.set_defaults(handler=_run_quality_gates)
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    return args.handler()


if __name__ == "__main__":
    sys.exit(main())

"""End-to-end tests for the ``dq snapshot-diff`` command line interface."""

import json
import subprocess
import sys
import unittest


PKG = [sys.executable, "-m", "data_quality", "snapshot-diff"]


def run_cli(payload_bytes):
    return subprocess.run(
        PKG,
        input=payload_bytes,
        capture_output=True,
    )


def run_json(obj):
    return run_cli(json.dumps(obj, ensure_ascii=False).encode("utf-8"))


def result(rule_id, dataset_id, field_id, sample_id, violated=True, value=None):
    return {
        "rule_id": rule_id,
        "dataset_id": dataset_id,
        "field_id": field_id,
        "sample_id": sample_id,
        "violated": violated,
        "value": value,
    }


def endpoint(dataset, field):
    return {"dataset": dataset, "field": field}


def edge(src_dataset, src_field, dst_dataset, dst_field, edge_type="upstream"):
    return {
        "source": endpoint(src_dataset, src_field),
        "target": endpoint(dst_dataset, dst_field),
        "type": edge_type,
    }


def path_node(dataset, field):
    return {"dataset_id": dataset, "field_id": field}


LINEAGE = {
    "datasets": ["ods", "dwd"],
    "fields": {"ods": ["name"], "dwd": ["label"]},
    "edges": [edge("dwd", "label", "ods", "name", "upstream")],
}

BASE_PAYLOAD = {
    "baseline": {
        "results": [
            result("r2", "dwd", "label", "样本-1", value="bad"),
            result("r1", "ods", "name", "样本-1", value="x"),
        ],
    },
    "current": {
        "results": [
            result("r1", "ods", "name", "样本-1", value="y"),
            result("r3", "dwd", "label", "样本-2", value=0),
        ],
    },
    "lineage": LINEAGE,
}


class CliSnapshotDiffSuccessTest(unittest.TestCase):
    def test_diff_output(self):
        proc = run_json(BASE_PAYLOAD)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertEqual(
            body,
            {
                "status": "ok",
                "summary": {
                    "baseline_violation_count": 2,
                    "current_violation_count": 2,
                    "new_count": 1,
                    "resolved_count": 1,
                    "persistent_count": 1,
                },
                "changes": [
                    {
                        "state": "persisted",
                        "rule_id": "r1",
                        "dataset_id": "ods",
                        "field_id": "name",
                        "sample_id": "样本-1",
                        "baseline_value": "x",
                        "current_value": "y",
                        "upstream_changes": [],
                        "paths": [],
                    },
                    {
                        "state": "resolved",
                        "rule_id": "r2",
                        "dataset_id": "dwd",
                        "field_id": "label",
                        "sample_id": "样本-1",
                        "baseline_value": "bad",
                        "current_value": None,
                        "upstream_changes": [
                            {
                                "rule_id": "r1",
                                "dataset_id": "ods",
                                "field_id": "name",
                                "sample_id": "样本-1",
                            }
                        ],
                        "paths": [
                            [
                                path_node("ods", "name"),
                                path_node("dwd", "label"),
                            ]
                        ],
                    },
                    {
                        "state": "new",
                        "rule_id": "r3",
                        "dataset_id": "dwd",
                        "field_id": "label",
                        "sample_id": "样本-2",
                        "baseline_value": None,
                        "current_value": 0,
                        "upstream_changes": [],
                        "paths": [],
                    },
                ],
            },
        )

    def test_single_line_of_output(self):
        proc = run_json(BASE_PAYLOAD)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        lines = proc.stdout.decode("utf-8").splitlines()
        self.assertEqual(len(lines), 1)

    def test_empty_snapshots(self):
        payload = {
            "baseline": {"results": []},
            "current": {"results": []},
            "lineage": LINEAGE,
        }
        proc = run_json(payload)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertEqual(body["status"], "ok")
        self.assertEqual(body["changes"], [])

    def test_nothing_written_to_stderr_on_success(self):
        proc = run_json(BASE_PAYLOAD)
        self.assertEqual(proc.stderr, b"")


class CliSnapshotDiffErrorTest(unittest.TestCase):
    def _assert_error(self, proc, code):
        self.assertEqual(proc.returncode, 2, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertEqual(set(body), {"error"})
        self.assertEqual(set(body["error"]), {"code", "message"})
        self.assertEqual(body["error"]["code"], code)
        self.assertTrue(body["error"]["message"])
        # The error object is the only top-level content, on one line.
        self.assertEqual(len(proc.stdout.decode("utf-8").splitlines()), 1)

    def test_invalid_json(self):
        self._assert_error(run_cli(b"{nope"), "INVALID_JSON")
        self._assert_error(run_cli(b'{"baseline": \xff}'), "INVALID_JSON")

    def test_payload_not_object(self):
        self._assert_error(run_json([1, 2]), "INVALID_SNAPSHOT_INPUT")
        self._assert_error(run_json("snapshots"), "INVALID_SNAPSHOT_INPUT")

    def test_invalid_snapshot_input_codes(self):
        bad = json.loads(json.dumps(BASE_PAYLOAD))
        del bad["lineage"]
        self._assert_error(run_json(bad), "INVALID_SNAPSHOT_INPUT")

        bad = json.loads(json.dumps(BASE_PAYLOAD))
        del bad["baseline"]["results"]
        self._assert_error(run_json(bad), "INVALID_SNAPSHOT_INPUT")

        bad = json.loads(json.dumps(BASE_PAYLOAD))
        bad["current"]["results"][0]["rule_id"] = ""
        self._assert_error(run_json(bad), "INVALID_SNAPSHOT_INPUT")

        bad = json.loads(json.dumps(BASE_PAYLOAD))
        bad["lineage"]["edges"][0]["type"] = "sideways"
        self._assert_error(run_json(bad), "INVALID_SNAPSHOT_INPUT")

        bad = json.loads(json.dumps(BASE_PAYLOAD))
        bad["unexpected"] = True
        self._assert_error(run_json(bad), "INVALID_SNAPSHOT_INPUT")

    def test_unknown_snapshot_reference_code(self):
        bad = json.loads(json.dumps(BASE_PAYLOAD))
        bad["baseline"]["results"][0]["dataset_id"] = "ghost"
        self._assert_error(run_json(bad), "UNKNOWN_SNAPSHOT_REFERENCE")

        bad = json.loads(json.dumps(BASE_PAYLOAD))
        bad["current"]["results"][0]["field_id"] = "ghost"
        self._assert_error(run_json(bad), "UNKNOWN_SNAPSHOT_REFERENCE")

    def test_error_precedence(self):
        self._assert_error(run_cli(b"{"), "INVALID_JSON")
        bad = json.loads(json.dumps(BASE_PAYLOAD))
        bad["current"]["results"][0]["dataset_id"] = "ghost"
        bad["lineage"]["edges"][0]["type"] = "bad"
        self._assert_error(run_json(bad), "INVALID_SNAPSHOT_INPUT")

    def test_nothing_written_to_stderr_on_error(self):
        proc = run_json([1])
        self.assertEqual(proc.returncode, 2)
        self.assertEqual(proc.stderr, b"")


if __name__ == "__main__":
    unittest.main()

